<?php
declare(strict_types=1);
require __DIR__.'/../bootstrap.php';
use Ismile\App;use Ismile\Db;use Ismile\WorkshopCash;use Ismile\WorkshopCatalog;use Ismile\WorkshopCheckout;use Ismile\Office;use Ismile\UserError;
if(App::isLive()||!str_starts_with((string)App::config('db.name'),'ismile_workshop_test_online_')||App::config('payments.psoola.api_base')!=='http://127.0.0.1:8832')throw new RuntimeException('Isolated workshop test database required.');
$passed=0;$check=static function(string $name,bool $ok)use(&$passed):void{if(!$ok)throw new RuntimeException('FAILED: '.$name);echo 'PASS: '.$name.PHP_EOL;$passed++;};
$reject=static function(callable $fn):bool{try{$fn();return false;}catch(UserError){return true;}};
$seed=static function(string $suffix,string $status='paid'):array{$id=Db::insert('registrations',['ref'=>'CA'.strtoupper(bin2hex(random_bytes(5))),'first_name'=>'Cash','father_name'=>'Workshop','grandfather_name'=>$suffix,'email'=>'cash-'.$suffix.'@example.invalid','phone'=>'+9647501234567','city'=>'Sulaimani','specialty'=>'gp','ticket_type'=>'professional','status'=>$status,'comp_reason'=>$status==='complimentary'?'Fixture':null,'view_nonce'=>bin2hex(random_bytes(16)),'created_at'=>App::now(),'updated_at'=>App::now(),'paid_at'=>App::now()]);return Db::one('SELECT * FROM registrations WHERE id=?',[$id]);};
$id='simplified-direct-veneers';$person=$seed('pending');$free=$seed('guest','complimentary');$cancelled=$seed('cancelled','cancelled');$owner=Db::one("SELECT * FROM admin_users WHERE role='owner' LIMIT 1");
$check('Only paid summit attendees can request cash',$reject(fn()=>WorkshopCash::request($id,'unknown@example.invalid'))&&$reject(fn()=>WorkshopCash::request($id,$free['email']))&&$reject(fn()=>WorkshopCash::request($id,$cancelled['email'])));
$check('Invalid email is rejected',$reject(fn()=>WorkshopCash::request($id,'bad')));
$before=WorkshopCatalog::one($id,true);$fixtureBefore=json_decode(file_get_contents('http://127.0.0.1:8832/fixture'),true);
$result=WorkshopCash::request($id,'  '.strtoupper($person['email']).' ');$request=Db::one('SELECT * FROM workshop_cash_requests WHERE registration_id=?',[$person['id']]);
$check('Cash method and quoted amount are saved',$result===['ok'=>true,'cashRequested'=>true]&&$request['payment_method']==='cash'&&(int)$request['amount']===$before['price']);
$check('Request never claims payment or creates a booking',!isset($result['redirect'])&&!Db::value('SELECT id FROM workshop_bookings WHERE registration_id=?',[$person['id']]));
$check('Repeated submission is idempotent',WorkshopCash::request($id,$person['email'])===$result&&(int)Db::value('SELECT COUNT(*) FROM workshop_cash_requests WHERE registration_id=?',[$person['id']])===1);
$check('Unpaid request appears for staff',in_array((string)$request['id'],array_map(static fn($r)=>(string)$r['id'],WorkshopCash::pending($id)),true));
$after=WorkshopCatalog::one($id,true);$fixtureAfter=json_decode(file_get_contents('http://127.0.0.1:8832/fixture'),true);
$check('Cash request does not reserve inventory or create a provider order',$after['seatsLeft']===$before['seatsLeft']&&$fixtureAfter['creations']===$fixtureBefore['creations']&&$fixtureAfter['direct']===$fixtureBefore['direct']);
$check('Unauthorized user cannot record cash',$reject(fn()=>Office::addWorkshop($person,['role'=>'viewer','id'=>$owner['id']],['workshop'=>$id,'payment_status'=>'paid','paid_how'=>'cash','amount_paid'=>$before['price']])));
$check('Incorrect cash amount cannot be marked paid',$reject(fn()=>Office::addWorkshop($person,$owner,['workshop'=>$id,'payment_status'=>'paid','paid_how'=>'cash','amount_paid'=>1])));
Office::addWorkshop($person,$owner,['workshop'=>$id,'payment_status'=>'paid','paid_how'=>'cash','amount_paid'=>$before['price']]);$booking=Db::one('SELECT * FROM workshop_bookings WHERE registration_id=?',[$person['id']]);
$check('Collected cash saves paid status, amount and staff identity',$booking['payment_status']==='paid'&&$booking['paid_how']==='cash'&&(int)$booking['amount_paid']===$before['price']&&(int)$booking['paid_recorded_by']===(int)$owner['id']&&$booking['paid_at']!==null);
$check('Handled request leaves pending list',!in_array((string)$request['id'],array_map(static fn($r)=>(string)$r['id'],WorkshopCash::pending($id)),true));
$check('Duplicate payment and request are blocked',$reject(fn()=>Office::addWorkshop($person,$owner,['workshop'=>$id]))&&$reject(fn()=>WorkshopCash::request($id,$person['email'])));
$online=$seed('online');WorkshopCheckout::start($id,$online['email']);$check('Open online payment blocks a cash request',$reject(fn()=>WorkshopCash::request($id,$online['email'])));
$sold=$seed('sold');file_get_contents('http://127.0.0.1:8832/fixture/stock?workshop='.$id.'&available=0');
$check('Sold out workshop rejects a new request',$reject(fn()=>WorkshopCash::request($id,$sold['email']))&&!Db::value('SELECT id FROM workshop_cash_requests WHERE registration_id=?',[$sold['id']]));
file_get_contents('http://127.0.0.1:8832/fixture/stock?workshop='.$id.'&available='.$before['seatsLeft']);
$company=(string)Db::value("SELECT id FROM workshops WHERE organizer='company' LIMIT 1");$check('Company workshops retain phone registration',$company!==''&&$reject(fn()=>WorkshopCash::request($company,$sold['email'])));
$check('Free workshop retains its free registration flow',$reject(fn()=>WorkshopCash::request('local-free-workshop',$sold['email'])));
echo $passed.' workshop cash checks passed.'.PHP_EOL;
